\u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u043f\u043e\u0441\u0442\u043e\u044f\u043d\u043d\u044b\u0445 \u0443\u0441\u0438\u043b\u0438\u0439 \u043f\u0440\u0435\u043f\u043e\u0434\u0430\u0432\u0430\u0442\u0435\u043b\u044f, \u0441\u0438\u0441\u0442\u0435\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0438 \u043f\u043b\u0430\u043d\u043e\u043c\u0435\u0440\u043d\u043e\u0439 \u0440\u0430\u0431\u043e\u0442\u044b \u043f\u043e \u0444\u043e\u0440\u043c\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044e \u0447\u0443\u0432\u0441\u0442\u0432 \u0438 \u0441\u043e\u0437\u043d\u0430\u043d\u0438\u044f.<br \\\/>\u0412\u0441\u0435 \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u0438 \u0445\u043e\u0442\u044f\u0442, \u0447\u0442\u043e\u0431\u044b \u0438\u0445 \u0440\u0435\u0431\u0435\u043d\u043e\u043a \u0431\u044b\u043b \u0434\u043e\u0431\u0440\u044b\u043c, \u0443\u043c\u043d\u044b\u043c, \u043f\u043e\u0440\u044f\u0434\u043e\u0447\u043d\u044b\u043c \u0438 \u0431\u043b\u0430\u0433\u043e\u0432\u043e\u0441\u043f\u0438\u0442\u0430\u043d\u043d\u044b\u043c. \u041d\u043e, \u043a \u0441\u043e\u0436\u0430\u043b\u0435\u043d\u0438\u044e, \u0432 \u0441\u043e\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e\u043c \u043e\u0431\u0449\u0435\u0441\u0442\u0432\u0435 \u0437\u0430\u0447\u0430\u0441\u0442\u0443\u044e \u0434\u0435\u0442\u0438 \u0440\u0430\u0441\u0442\u0443\u0442 \u043a\u0430\u043f\u0440\u0438\u0437\u043d\u044b\u043c\u0438, \u0436\u0430\u0434\u043d\u044b\u043c\u0438, \u0434\u0440\u0430\u0447\u043b\u0438\u0432\u044b\u043c\u0438 \u0438 \u043d\u0435\u043f\u043e\u0441\u043b\u0443\u0448\u043d\u044b\u043c\u0438. \u0427\u0442\u043e \u0436\u0435 \u0434\u0435\u043b\u0430\u0442\u044c? \u041c\u043e\u0436\u043d\u043e \u0438\u043c\u0435\u0442\u044c \u0431\u043e\u043b\u044c\u0448\u043e\u0439 \u0431\u0430\u0433\u0430\u0436 \u0437\u043d\u0430\u043d\u0438\u0439, \u043d\u043e \u043f\u0440\u0438 \u044d\u0442\u043e\u043c \u043d\u0435 \u0438\u043c\u0435\u0442\u044c \u044d\u043b\u0435\u043c\u0435\u043d\u0442\